  const stSel=m.querySelector('#esa-status'),locSel=m.querySelector('#esa-local');if(['RECOLHIDO','REMANEJADO','NÃO RECOLHIDO'].includes(statusAtual))stSel.value=statusAtual;if(statusAtual==='RECOLHIDO'&&['NTE','EGBA'].includes(localAtual))locSel.value=localAtual;
  const atualizarResumo=()=>{const st=stSel.value;m.querySelector('#esa-resumo-status').textContent=st;m.querySelector('#esa-resumo-local').textContent=st==='RECOLHIDO'?(locSel.options[locSel.selectedIndex]?.text||'—'):st==='REMANEJADO'?(destino?(destino.nome_escola||destino.nome||'Unidade selecionada'):'Selecione a instituição'):'Sem custodiante físico';};
  const ajustar=()=>{const st=stSel.value;m.querySelector('#esa-local-wrap').style.display=st==='RECOLHIDO'?'':'none';m.querySelector('#esa-dest-wrap').style.display=st==='REMANEJADO'?'block':'none';atualizarResumo()};m.querySelector('[data-close]').onclick=fechar;stSel.onchange=ajustar;locSel.onchange=atualizarResumo;ajustar();
  const busca=m.querySelector('#esa-dest-busca'),res=m.querySelector('#esa-dest-result'),sel=m.querySelector('#esa-dest-sel');busca.oninput=()=>{clearTimeout(timer);destino=null;sel.style.display='none';atualizarResumo();const t=busca.value.trim();if(t.length<2){res.style.display='none';return}timer=setTimeout(async()=>{try{const xs=await service().pesquisarInstituicaoDestinoRecolhimento(t,escola.id);res.innerHTML=xs.map(x=>`<button type="button" class="extd-btn" style="display:block;width:100%;text-align:left;margin:3px 0" data-rdest="${x.id}"><b>${esc(x.nome_escola||x.nome)}</b><br><small>Nº SIGEE ${esc(x.id)} · MEC ${esc(x.cod_mec||'—')} · ${esc(x.municipio||'')}</small></button>`).join('')||'Nenhuma instituição localizada.';res.style.display='block';res.querySelectorAll('[data-rdest]').forEach(b=>b.onclick=()=>{destino=xs.find(x=>String(x.id)===String(b.dataset.rdest));busca.value=destino.nome_escola||destino.nome||'';res.style.display='none';sel.innerHTML='<b>Destino solicitado:</b> '+esc(busca.value);sel.style.display='block';atualizarResumo()})}catch(e){res.textContent=e.message||e;res.style.display='block'}},250)};
  m.querySelector('#esa-enviar').onclick=async()=>{try{const st=stSel.value,loc=st==='RECOLHIDO'?locSel.value:null,just=m.querySelector('#esa-just').value.trim();if(st==='REMANEJADO'&&!destino)throw new Error('Selecione a instituição responsável pelo acervo.');if(!just)throw new Error('Informe a justificativa da solicitação.');if(st===statusAtual&&((st==='RECOLHIDO'&&norm(loc)===localAtual)||(st==='REMANEJADO'&&localAtual==='INSTITUICAO')||st==='NÃO RECOLHIDO'))throw new Error('Selecione uma alteração diferente da situação atual do acervo.');await service().solicitarAlteracaoAcervo(escola.id,{status_acervo:st,local_acervo:loc,destino_escola_id:destino?.id||null,justificativa:just});alert('Solicitação enviada para análise da SEC/Master.');fechar()}catch(e){alert(e.message||e)}};
