  m.querySelector('#eca-historico').onclick=async()=>{try{const [hs,ca]=await Promise.all([service().historicoCustodia(escola.id),service().custodiaAtual(escola.id)]);const hm=modal(`<h2>Histórico de custódia do acervo</h2><div class="extd-panel"><b>${esc(escola.nome_escola||escola.nome)}</b><p>MEC ${esc(escola.cod_mec||'—')} · ${esc(escola.municipio||'')}</p></div>${ca?`<div class="extd-panel"><b>Custódia atual:</b> ${esc(ca.local_atual_acervo||ca.custodia_tipo||'—')}<br><small>${ca.quantidade_caixas??0} caixa(s) · desde ${fmt(ca.data_movimentacao)}</small></div>`:''}${hs.length?`<div class="extd-grid">${hs.map(h=>`<article class="extd-card"><span class="extd-badge">${esc(String(h.tipo_movimentacao||'').replaceAll('_',' '))}</span><h3>${fmt(h.data_movimentacao)}</h3><p>${esc(h.origem_descricao||h.origem_tipo||'—')} → ${esc(h.destino_descricao||h.destino_tipo||'—')}</p><small>${h.quantidade_caixas!=null?esc(h.quantidade_caixas)+' caixa(s) · ':''}${h.registrado_por_nome?'Registrado por '+esc(h.registrado_por_nome):''}${h.observacao?' · '+esc(h.observacao):''}</small></article>`).join('')}</div>`:'<div class="extd-panel">Nenhuma movimentação registrada.</div>'}<div class="extd-actions">${ca&&String(ca.custodia_tipo||'').toUpperCase()==='NTE'?'<button class="extd-btn warn" id="eca-egba">Registrar envio à EGBA</button>':''}<button class="extd-btn primary" data-close>Fechar</button></div>`);hm.querySelector('[data-close]').onclick=fechar;hm.querySelector('#eca-egba')?.addEventListener('click',async()=>{try{const ref=prompt('Documento/termo de envio à EGBA (opcional):','')||'';const obs=prompt('Observação do encaminhamento (opcional):','')||'';if(!confirm('Confirmar a saída deste acervo do NTE e o envio para a EGBA?'))return;await service().enviarAcervoEgba(escola.id,{documento_referencia:ref,observacao:obs});alert('Envio à EGBA registrado. O acervo saiu do quantitativo sob custódia do NTE e o histórico foi preservado.');fechar();await carregarCatalogo();}catch(e){alert(e.message||e)}});}catch(e){alert(e.message||e)}};
